import{_ as a,H as e,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"13｜让 AI 当你的环境工程师：依赖、编译、启动、冒烟一把过","description":"","frontmatter":{},"headers":[{"level":2,"title":"环境搭建是老项目改造最大的坑","slug":"环境搭建是老项目改造最大的坑","link":"#环境搭建是老项目改造最大的坑","children":[]},{"level":2,"title":"让 AI 把环境一把搞定","slug":"让-ai-把环境一把搞定","link":"#让-ai-把环境一把搞定","children":[{"level":3,"title":"Step 1：依赖盘点","slug":"step-1-依赖盘点","link":"#step-1-依赖盘点","children":[]},{"level":3,"title":"Step 2A：本地安装方案（主推）","slug":"step-2a-本地安装方案-主推","link":"#step-2a-本地安装方案-主推","children":[]},{"level":3,"title":"Step 2B：依赖启停管理脚本","slug":"step-2b-依赖启停管理脚本","link":"#step-2b-依赖启停管理脚本","children":[]},{"level":3,"title":"Step 2C：Docker 方案（备选）","slug":"step-2c-docker-方案-备选","link":"#step-2c-docker-方案-备选","children":[]},{"level":3,"title":"Step 3：编译启动","slug":"step-3-编译启动","link":"#step-3-编译启动","children":[]},{"level":3,"title":"Step 4：接口冒烟","slug":"step-4-接口冒烟","link":"#step-4-接口冒烟","children":[]}]},{"level":2,"title":"把过程沉淀成长期资产","slug":"把过程沉淀成长期资产","link":"#把过程沉淀成长期资产","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/13｜让AI当你的环境工程师：依赖、编译、启动、冒烟一把过.md","filePath":"ClaudeCode企业级老项目改造实战/13｜让AI当你的环境工程师：依赖、编译、启动、冒烟一把过.md","lastUpdated":1779815445000}'),t={name:"ClaudeCode企业级老项目改造实战/13｜让AI当你的环境工程师：依赖、编译、启动、冒烟一把过.md"};function l(i,s,o,c,d,r){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="_13-让-ai-当你的环境工程师-依赖、编译、启动、冒烟一把过" tabindex="-1">13｜让 AI 当你的环境工程师：依赖、编译、启动、冒烟一把过 <a class="header-anchor" href="#_13-让-ai-当你的环境工程师-依赖、编译、启动、冒烟一把过" aria-label="Permalink to &quot;13｜让 AI 当你的环境工程师：依赖、编译、启动、冒烟一把过&quot;">​</a></h1><p>你好，我是 Robert。</p><p>第二部分我们把一个老项目从“完全不懂”摸到了“docs/ 五份资产 + CLAUDE.md + 一个 SKILL”的程度。但有一件事还没做： <strong>让项目真的在你电脑上跑起来</strong>。</p><p>这一讲开始进入第三部分。说一下这部分的定位： <strong>第三部分的工作流几乎对每个老项目都一样</strong>。不管你实践的是 Spring AI Alibaba Admin，还是你公司那个跑了五年的订单系统，前置工作的步骤都差不多：分析依赖、装中间件、编译启动、冒烟接口、摸清测试、必要时补出兜底测试。</p><p><strong>每一步的提示词都可以拿来即用，改改项目名就行</strong>。这是第三部分最高的“性价比”：不需要学方法论，照着跑就能快一两天。</p><p>13 讲处理的就是其中最折磨人的一部分： <strong>环境搭建</strong>。</p><h2 id="环境搭建是老项目改造最大的坑" tabindex="-1">环境搭建是老项目改造最大的坑 <a class="header-anchor" href="#环境搭建是老项目改造最大的坑" aria-label="Permalink to &quot;环境搭建是老项目改造最大的坑&quot;">​</a></h2><p>接手过老项目的人都懂这个折磨。</p><p><strong>clone 下来</strong> <code>mvn install</code> <strong>一跑，先报缺 Nacos、再报 MySQL 版本不对、再报某个端口冲突、再报对接的内部服务连不上。</strong> 每一项都得 google 半天、装一遍、配一遍、试一遍，一天就这么过去了，一脸绝望。</p><p>更难的是 <strong>README 不会告诉你完整的中间件清单</strong>。Nacos 写在 README 上，OTel Collector 在 application-prod.yml 里藏着，Redis 是某个 starter 间接拉的。照着 README 跑能跑通的概率不到一半。</p><p>而且这些中间件装好了还要管。每次电脑重启所有服务都停了，第二天上班得一个个起。Mac 上 brew services 还能管一部分，Nacos / OTel Collector 这种自己下载 jar 跑的服务一断电就没了，每次手动 <code>sh startup.sh</code> 一个个拉起来。</p><p>这一讲让 AI 当你的环境工程师，把这套折磨自动化掉。四步走： <strong>依赖盘点 → 本地安装 + 启停管理 → 编译启动 → 接口冒烟</strong>。</p><p>跑完后，你电脑上会有一个真正“活着”的 Spring AI Alibaba Admin。中途 AI 自己 debug 自己修复，你不需要每个错误都介入。这就是释放生产力，也让你更加轻松，不用天天纠结这些细节问题。</p><h2 id="让-ai-把环境一把搞定" tabindex="-1">让 AI 把环境一把搞定 <a class="header-anchor" href="#让-ai-把环境一把搞定" aria-label="Permalink to &quot;让 AI 把环境一把搞定&quot;">​</a></h2><p>下面是四步法的完整提示词。每一条都可以直接拷贝到 Claude Code 跑，改改项目名就能用在自己公司项目上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/50c426646e8deaa3885ea911711a64df.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/50c426646e8deaa3885ea911711a64df.png" alt=""></a></p><h3 id="step-1-依赖盘点" tabindex="-1">Step 1：依赖盘点 <a class="header-anchor" href="#step-1-依赖盘点" aria-label="Permalink to &quot;Step 1：依赖盘点&quot;">​</a></h3><p>第一步先让 AI 把这个项目运行需要的所有外部依赖列清楚。这一步的产出是后面所有步骤的基础。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>综合看 docs/external-deps.svg、application*.yml、pom.xml、README，</span></span>
<span class="line"><span>给我列一份这个项目运行需要的完整外部依赖清单。</span></span>
<span class="line"><span>每个依赖列出：名字、版本要求（精确到主版本）、默认端口、</span></span>
<span class="line"><span>连接信息、初始化要求（建库、配 Nacos 命名空间等）。</span></span>
<span class="line"><span>保存到 docs/env-checklist.md。</span></span></code></pre></div><p>产出： <code>docs/env-checklist.md</code>。这份清单可能列出 MySQL 8.x、Nacos 2.x、OTel Collector、外加几个模型 API 的环境变量配置。</p><p>产出的结果是下图，你会发现需要依赖很多组件。其实这里你可以看到，提示词的重要性。如果要让我们整理这么多依赖，要耗费大量的时间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/310a91f6192f31037918d47c36bddbd5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/310a91f6192f31037918d47c36bddbd5.png" alt="图片"></a></p><p>review 重点：</p><ul><li><p><strong>和 docs/external-deps.svg 对得上</strong>。08 讲画过的外部依赖图在这里复用，AI 列的清单不应该和图有出入。如果有出入，要么图错了，要么清单错了，要让 AI 解释清楚。</p></li><li><p><strong>版本号有依据</strong>。AI 不能瞎写“MySQL 用 8.0 就行”。版本要么来自 pom.xml（数据库连接池要求的最低版本）、要么来自 README（项目作者明确说过测过哪个版本）。让 AI 在每个版本号后面标注来源。</p></li><li><p><strong>初始化要求要细</strong>。Nacos 不是装上就能用，要建命名空间、推几个配置项。MySQL 不是建好库就行，要跑初始化 SQL。这些动作清单里都要有。</p></li></ul><h3 id="step-2a-本地安装方案-主推" tabindex="-1">Step 2A：本地安装方案（主推） <a class="header-anchor" href="#step-2a-本地安装方案-主推" aria-label="Permalink to &quot;Step 2A：本地安装方案（主推）&quot;">​</a></h3><p>依赖列清楚了，下一步装。我主推本地安装。原因： <strong>本地装的中间件用起来轻、断电不跑等问题都好处理，性能也比 Docker 在 Mac 上好</strong>（特别是 Mac M 系列芯片下 Docker 有 ARM 兼容问题）。Docker 方案，Step 2C 顺手给一份给偏好 Docker 的同学。</p><p>让 AI 不只是给脚本，直接执行装上。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读 docs/env-checklist.md，给我生成一份本地安装脚本，</span></span>
<span class="line"><span>保存到 scripts/install-deps.sh。</span></span>
<span class="line"><span>- 用 brew（macOS）或 apt（Linux）装中间件</span></span>
<span class="line"><span>- 包含每个中间件的初始化（建库 SQL、Nacos 配置等）</span></span>
<span class="line"><span>- 不会的依赖（比如某个 jar 包要下）写清楚下载链接和放哪</span></span>
<span class="line"><span></span></span>
<span class="line"><span>生成完直接执行这个脚本。执行过程遵循自主修复原则:</span></span>
<span class="line"><span>- 任何一步失败，先看报错信息</span></span>
<span class="line"><span>- 自己判断原因（版本不对、源问题、权限问题、依赖缺失）</span></span>
<span class="line"><span>- 自己修（换源、换版本、加 sudo、装前置依赖）</span></span>
<span class="line"><span>- 修完重试，跑通为止</span></span>
<span class="line"><span>- 不要每个错误都问我</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果同一个错误连续修 3 次还不行，停下来汇报具体卡在哪。</span></span>
<span class="line"><span>其他情况一律自己解决。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终输出一份 scripts/install-log.md，记录每个中间件</span></span>
<span class="line"><span>最终用了什么命令装上、过程中遇到什么问题、怎么修的。</span></span></code></pre></div><p>产出： <code>scripts/install-deps.sh</code> + <code>scripts/install-log.md</code>。看运行结果，这个提示词很完美，AI执行了正确的结果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/9ca6ef19b18462941a8d658a68a2cd04.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/9ca6ef19b18462941a8d658a68a2cd04.png" alt="图片"></a></p><p>这条提示词的关键设计有两点：</p><ul><li><p><strong>“3 次还不行就停”是必须的兜底</strong>。不带这条会出现 AI 改一个配置、报新错、再改、再报新错的死循环，几小时停不下来。3 次同样的错误说明问题超出 AI 判断能力，必须人介入。这是从实际跑出来的经验。</p></li><li><p><strong>要求输出 install-log.md</strong>。这份踩坑日志比脚本本身更值钱。下次同项目重装能照着跑，团队新人看日志知道项目的“环境怪癖”，某天 brew 默认装 MySQL 9 和项目要求的 8 冲突时日志里有“我们用 <code>brew install mysql@8</code> 而不是 <code>brew install mysql</code>”这种关键决策。</p></li></ul><p>review 重点：</p><ul><li><p>脚本是不是对每个中间件都包含“装 + 初始化 + 验证装上”三步。</p></li><li><p>install-log.md 是不是真实反映了过程。</p></li><li><p>3 次失败的兜底有没有触发过、AI 有没有死循环。</p></li></ul><h3 id="step-2b-依赖启停管理脚本" tabindex="-1">Step 2B：依赖启停管理脚本 <a class="header-anchor" href="#step-2b-依赖启停管理脚本" aria-label="Permalink to &quot;Step 2B：依赖启停管理脚本&quot;">​</a></h3><p>中间件装好了，但还有一件事：电脑一关再开，所有服务都停了，每次手动起一遍特别烦。让 AI 生成一组启停管理脚本，把所有中间件的启停拉齐到统一命令。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于 Step 2A 装好的中间件，生成三个脚本到 scripts/ 下：</span></span>
<span class="line"><span>- deps-start.sh：一键启动所有依赖中间件</span></span>
<span class="line"><span>- deps-stop.sh：一键停止所有依赖中间件</span></span>
<span class="line"><span>- deps-status.sh：查看每个中间件的运行状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>考虑混合场景：有的用 brew services 管，有的是手动 jar，</span></span>
<span class="line"><span>有的是 systemd。脚本要能处理这几种。</span></span>
<span class="line"><span>启动后等服务就绪再返回，不要&quot;启动了但还没 ready&quot;。</span></span>
<span class="line"><span>status 脚本要打印每个中间件的运行状态和端口监听情况。</span></span></code></pre></div><p>产出： <code>scripts/deps-start.sh</code> / <code>deps-stop.sh</code> / <code>deps-status.sh</code>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/9d733dd1b681ba13d05a2731b2f343a6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/9d733dd1b681ba13d05a2731b2f343a6.png" alt="图片"></a></p><p>每天上班 <code>./scripts/deps-start.sh</code>，下班 <code>./scripts/deps-stop.sh</code>，比 Docker 方案还方便（Docker 还要 docker-compose up）。这才是本地开发的应有姿态。</p><p>review 重点：</p><ul><li><p><strong>启动顺序要对</strong>。Nacos 要在 OTel Collector 之前启动，因为 Collector 可能用 Nacos 做服务发现。MySQL 要在应用之前启动。AI 默认可能并行启动，让它按依赖顺序串行起。</p></li><li><p><strong>status 脚本输出要清晰</strong>。一眼看出哪个起来了、哪个挂了，比 <code>ps aux | grep</code> 一个个查方便十倍。</p></li></ul><h3 id="step-2c-docker-方案-备选" tabindex="-1">Step 2C：Docker 方案（备选） <a class="header-anchor" href="#step-2c-docker-方案-备选" aria-label="Permalink to &quot;Step 2C：Docker 方案（备选）&quot;">​</a></h3><p>我主推本地安装，但我想有些同学可能偏好 Docker，给一条提示词让 AI 顺手出一份 Docker 方案。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顺手给一份 docker-compose.dev.yml，把所有依赖打包成 docker。</span></span>
<span class="line"><span>偏好 Docker 的同学可以用这个替代 Step 2A 和 2B。</span></span>
<span class="line"><span>版本号、端口、初始化脚本要齐全。</span></span>
<span class="line"><span>保存到项目根目录。不用运行</span></span></code></pre></div><p>产出： <code>docker-compose.dev.yml</code>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/f521b09b5775cedf36539835a382c284.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/f521b09b5775cedf36539835a382c284.png" alt="图片"></a></p><p>如果你偏好 Docker，直接 <code>docker-compose -f docker-compose.dev.yml up -d</code> 就好。本地装那套 install + start/stop 全部跳过。这是给大家的第二条路。</p><h3 id="step-3-编译启动" tabindex="-1">Step 3：编译启动 <a class="header-anchor" href="#step-3-编译启动" aria-label="Permalink to &quot;Step 3：编译启动&quot;">​</a></h3><p>中间件起来了，开始编译启动应用本身。这一步同样让 AI 自主修复。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中间件已经起来了（用 ./scripts/deps-status.sh 确认）。</span></span>
<span class="line"><span>现在帮我跑 mvn clean package + 启动应用。</span></span>
<span class="line"><span>启动过程同样遵循自主修复原则</span></span>
<span class="line"><span>（参照 Step 2A 的兜底机制：连续 3 次同一错误才停下来汇报）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>启动成功后告诉我应用监听的端口、管理界面地址。</span></span>
<span class="line"><span>失败和修复的过程记到 docs/startup-log.md。</span></span></code></pre></div><p>产出：项目跑起来了 + <code>docs/startup-log.md</code>。编译启动的常见错误比依赖安装更多：</p><ul><li><p>Java 版本不对（项目要 17，本地是 21 或 11）</p></li><li><p>Maven 仓库连不上，或者拉的依赖版本和 lockfile 对不上</p></li><li><p>端口被占用（8080、8848 这些常用端口被别的服务占了）</p></li><li><p>配置文件缺失（application-dev.yml 不在仓库里，需要从 application.yml 拷一份改）</p></li><li><p>Nacos 配置没推（应用启动时连 Nacos 拉不到配置）</p></li></ul><p>每一类 AI 都有处理经验。给它自主修复授权，多数能自己搞定。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/5246dee07ed2e06feb37c472d950a97a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/5246dee07ed2e06feb37c472d950a97a.png" alt="图片"></a></p><p>review 重点：</p><ul><li><p>日志没报 ERROR。</p></li><li><p>端口监听正常。</p></li><li><p>管理界面 <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a> 能打开（页面可能要登录，能看到登录页就算活着）。</p></li></ul><p>然后我增加问了一句：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有前端页面吗？也启动一下，给我访问地址</span></span></code></pre></div><p>然后结果是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/2af2b0b7b6cdb870737b697ee6d5050c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/2af2b0b7b6cdb870737b697ee6d5050c.png" alt="图片"></a></p><p>看这个输出就很舒服。然后页面也出来了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/yy7c9e983871dbbf70fe583c37bca6bb.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/yy7c9e983871dbbf70fe583c37bca6bb.png" alt="图片"></a></p><p>其实到这里，你就可以看出来这套提示词和本节课思路的好处了。</p><h3 id="step-4-接口冒烟" tabindex="-1">Step 4：接口冒烟 <a class="header-anchor" href="#step-4-接口冒烟" aria-label="Permalink to &quot;Step 4：接口冒烟&quot;">​</a></h3><p>最后一步：用 curl 跑几个核心接口，确认项目真的活了。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读 docs/api-list.md，挑 5 个最核心的接口（覆盖登录、Prompt、</span></span>
<span class="line"><span>Dataset、Evaluator、Trace 几大模块），用 curl 跑一遍。</span></span>
<span class="line"><span>返回 200 算通过，返回错误的列出来。</span></span>
<span class="line"><span>最后输出一份 docs/smoke-test-result.md。</span></span></code></pre></div><p>产出： <code>docs/smoke-test-result.md</code>。跑完这一步， <strong>项目算“真的活了”</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/3bdcddb3da0fb55f2b0c8a9c113aa3f7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/3bdcddb3da0fb55f2b0c8a9c113aa3f7.png" alt="图片"></a></p><p>然后我看了一眼数据库，都建好了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/c47bfc1221e8cca9ffd8029658406528.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/977524/c47bfc1221e8cca9ffd8029658406528.png" alt="图片"></a></p><p>review 重点：</p><ul><li><p>选的接口是不是真的核心（不是挑了几个最简单的 GET 接口）。</p></li><li><p>返回结构和 api-list.md 描述的一致。</p></li><li><p>如果有接口返回错误，AI 是不是标出来了（不要为了“全绿”故意挑能过的）。</p></li></ul><h2 id="把过程沉淀成长期资产" tabindex="-1">把过程沉淀成长期资产 <a class="header-anchor" href="#把过程沉淀成长期资产" aria-label="Permalink to &quot;把过程沉淀成长期资产&quot;">​</a></h2><p>四步跑完，你手里有了一个真正活着的项目，加这些产出：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├── env-checklist.md          ← 依赖清单</span></span>
<span class="line"><span>├── startup-log.md            ← 启动踩坑日志</span></span>
<span class="line"><span>└── smoke-test-result.md      ← 冒烟结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>scripts/</span></span>
<span class="line"><span>├── install-deps.sh           ← 一次性装齐</span></span>
<span class="line"><span>├── install-log.md            ← 安装踩坑日志</span></span>
<span class="line"><span>├── deps-start.sh             ← 每天用</span></span>
<span class="line"><span>├── deps-stop.sh              ← 每天用</span></span>
<span class="line"><span>└── deps-status.sh            ← 每天用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker-compose.dev.yml        ← Docker 备选</span></span></code></pre></div><p>这些产物有两个去向。</p><p><strong>一个产物给团队</strong>：把 install-log.md + startup-log.md 整理成一份 <code>docs/setup-guide.md</code>，下个新人来照着跑。这件事 AI 帮你做：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于 scripts/install-log.md 和 docs/startup-log.md，</span></span>
<span class="line"><span>整理一份给新人看的 setup-guide.md，</span></span>
<span class="line"><span>包含：前置条件、装中间件步骤、启动命令、常见踩坑、验证清单。</span></span>
<span class="line"><span>保存到 docs/setup-guide.md。</span></span></code></pre></div><p><strong>另一个产物挖成 SKILL</strong>：整套“依赖盘点 → 装中间件 → 启动 → 冒烟”流程做成一个 SKILL，下次任何新项目（或者重置环境）都能一键跑。这就是 11 讲挖到的第二个 SKILL。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于这次环境搭建的全流程，给我生成一个 env-bootstrap 的 SKILL，</span></span>
<span class="line"><span>保存到 .claude/skills/env-bootstrap/SKILL.md。</span></span>
<span class="line"><span>触发场景：新接手项目、重置环境、定期验证环境健康。</span></span>
<span class="line"><span>步骤：依赖盘点 → 装中间件 → 启停脚本 → 编译启动 → 接口冒烟。</span></span>
<span class="line"><span>allowed-tools 限制到 Read, Bash, Write。</span></span></code></pre></div><p>跑完 13 讲，你积累的 SKILL 数量从 1 个变成 2 个： <code>docs-auto-sync</code> + <code>env-bootstrap</code>。两个都是“反复做但没沉淀”的高价值流程，还有一个给你留着自己挖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲讲了一件事： <strong>让 AI 当你的环境工程师，把环境搭建从“半天到一天的折磨”压到“半小时跑完”</strong>。</p><p>四步法：依赖盘点 → 本地安装 + 启停管理（主线，Docker 备选）→ 编译启动 → 接口冒烟。在这节课中，安装依赖的部分你可能需要关注下，因为本地环境的差异性，安装可能会失败，需要你给AI提供帮助，比如提供权限等。</p><p>每一步都让 AI 自主修复。3 次失败兜底防死循环。所有踩坑过程沉淀成日志，最终汇成 setup-guide.md 和 env-bootstrap SKILL，成为团队和你自己的长期资产。</p><p>整个第三部分的提示词都是这个特点：拿来即用，改改项目名就能在自己公司项目跑。这一讲是最典型的一讲。</p><p>下一讲我们摸清这个项目的测试现状：能跑通吗？覆盖度怎样？动手改造之前要不要补测试？</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你最近一次接手老项目搭环境花了多长时间？这一讲的四步法，哪一步让你眼前一亮？回想一下你当时手动做的那些事，哪些是 AI 现在能替你做的？</p></li><li><p>你电脑上现在跑着多少个开发依赖（MySQL、Redis、Nacos 等）？有 start / stop 统一管理脚本吗？如果没有，每次电脑重启你是怎么处理这些服务的？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,96)])])}const g=a(t,[["render",l]]);export{h as __pageData,g as default};
